  evidence={'reviewer':'math81_boundary_homological','method':'Actual current mathematical body and complete relevant argument read, followed by independent case analysis.','analysis':reason,'source':s['source'],'original_disposition_retained':original.get('status')==proposed['status']}
  # Specific mathematical replacement evidence is supplied for every row, rather than mechanically upholding invalid old boilerplate.
